function icon(name, extra = '') { name=({game:'gamepad',book:'book-open',help:'info',star:'spark'})[name]||name; return `<svg class="icon ${e(extra)}" viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.message}</svg>`; }
function paintIcons(scope = document) { $$('[data-icon]', scope).forEach(el => { el.innerHTML = icon(el.dataset.icon); }); }
const colors = {violet:'#ad93ff',purple:'#ad93ff',cyan:'#68cfd1',teal:'#68cfd1',blue:'#83b1ec',green:'#7acfaa',amber:'#dfb578',orange:'#dfa178',rose:'#d790b6',pink:'#d790b6',red:'#e0939d',slate:'#9ba9c7'};
function tone(value) { return colors[value] || (/^#[\da-f]{3}([\da-f]{3})?$/i.test(value || '') ? value : colors.violet); }
function avatar(user, size = '') { const name = user?.name || tr('ui.user.fallback'); const initials = user?.initials || name.split(/\s+/).slice(0,2).map(x => x[0] || '').join('').toUpperCase(); return `<span class="avatar ${size ? 'avatar-'+e(size) : ''}" style="--tone:${tone(user?.color)}" aria-hidden="true">${e(initials)}</span>`; }
function count(value) { return new Intl.NumberFormat(activeLocale()).format(Number(value) || 0); }
function noun(value,unit) { const form=new Intl.PluralRules(activeLocale()).select(Number(value)||0);return tr(`ui.count.${unit}.${form}`,{},tr(`ui.count.${unit}.other`)); }
function counted(value,unit) { return `${count(value)} ${noun(value,unit)}`; }
function compact(value) { return new Intl.NumberFormat(activeLocale(),{notation:'compact',maximumFractionDigits:1}).format(Number(value) || 0); }
function parseDate(value) { if (!value) return null; const s = String(value); const d = new Date(/^\d{4}-\d\d-\d\d \d\d:\d\d:\d\d$/.test(s) ? s.replace(' ','T')+'Z' : s); return Number.isNaN(+d) ? null : d; }
function relative(value) { const date=parseDate(value);if(!date)return '';const diff=Math.min(0,(date.getTime()-Date.now())/1000);if(diff>-60)return tr('ui.common.now');const format=new Intl.RelativeTimeFormat(activeLocale(),{numeric:'auto'});if(diff>-3600)return format.format(Math.ceil(diff/60),'minute');if(diff>-86400)return format.format(Math.ceil(diff/3600),'hour');if(diff>-604800)return format.format(Math.ceil(diff/86400),'day');return new Intl.DateTimeFormat(activeLocale(),{day:'numeric',month:'short'}).format(date); }
function dateTitle(value) { const d=parseDate(value);return d?new Intl.DateTimeFormat(activeLocale(),{dateStyle:'long',timeStyle:'short'}).format(d):''; }
function role(user) { return user?.role === 'admin' ? `<span class="role-badge">${tx('ui.common.admin')}</span>` : user?.role === 'moderator' ? `<span class="role-badge moderator">${tx('ui.common.moderator')}</span>` : ''; }
function isMod() { return ['admin','moderator'].includes(state.user?.role); }
function pluginEnabled(key) { return !!state.bootstrap?.plugins?.find(p => (p.id || p.key) === key)?.enabled; }
function empty(title, description, iconName = 'message', action = '') { return `<div class="empty-state"><div class="empty-icon">${icon(iconName)}</div><h3>${e(title)}</h3><p>${e(description)}</p>${action}</div>`; }
function loading() { return `<div class="panel loading-panel"><div class="skeleton skeleton-line"></div><div class="skeleton skeleton-line"></div><div class="skeleton skeleton-line"></div><span class="loading-label">${tx('ui.common.loading_content')}</span></div>`; }
function toast(message, error = false) { const div = document.createElement('div');div.className='toast'+(error?' error':'');div.innerHTML=icon(error?'alert':'check-circle')+`<span>${e(message)}</span>`;$('#toast-region').append(div);setTimeout(()=>div.remove(),error?6500:4200); }

const state = {bootstrap:null,user:null,csrf:$('meta[name="csrf-token"]')?.content||'',viewToken:0,thread:null,threadPage:1,route:null,sort:'latest',page:1,shouts:[],lastShoutId:0,shoutsInFlight:false,rankings:[],admin:null,adminTab:'settings',adminUserMatches:null,adminUserTerm:'',groupData:null,groupUserMatches:null,groupUserTerm:'',languageData:null,reportData:null,reportStatus:'open',reportPage:1,importFile:null,importReport:null,importPreviewOK:false};


async function request(url, options = {}, retried = false) {
    const init = {method:'GET',credentials:'same-origin',...options};
    init.headers = {Accept:'application/json',...(preferredLocale?{'X-WojteX-Locale':preferredLocale}:{}),...(options.headers||{})};
    if (init.body && !(init.body instanceof FormData) && typeof init.body !== 'string') { init.headers['Content-Type']='application/json'; init.body=JSON.stringify(init.body); }
    if(!['GET','HEAD'].includes(init.method.toUpperCase()))init.headers['X-CSRF-TOKEN']=state.csrf;
    const response = await fetch(url,init);
    let data;try {data=await response.json();}catch(_){data={message:response.ok?tr('ui.common.invalid_response'):tr('ui.common.request_failed',{status:response.status})};}
    if(response.status===419&&!retried){const boot=await fetch('/api/bootstrap',{credentials:'same-origin',headers:{Accept:'application/json',...(preferredLocale?{'X-WojteX-Locale':preferredLocale}:{})}});if(boot.ok){const b=await boot.json();state.csrf=b.csrf_token||state.csrf;return request(url,options,true);}}
    if(!response.ok){const validation=data.errors?Object.values(data.errors).flat().join('\n'):null;const err=new Error(validation||data.message||tr('ui.common.error'));err.status=response.status;throw err;}
    return data;
}
async function loadBootstrap() {
    // Password changes can invalidate an existing session while this SPA is open.
    // The middleware clears that session and returns 401; one guest bootstrap
    // retry restores a usable login page rather than a permanent error screen.
    try { state.bootstrap=await request('/api/bootstrap'); }
    catch (err) {
        if (err.status!==401) throw err;
        state.user=null;
        state.bootstrap=await request('/api/bootstrap');
    }
    acceptI18n(state.bootstrap.i18n);state.user=state.bootstrap.user;state.csrf=state.bootstrap.csrf_token||state.csrf;
    const settings=state.bootstrap.settings||{};WojtexAppearance.apply(settings);
    document.title=`${settings.site_name||'WojteX Forum'} — by Swir`;$('#version-label').textContent=state.bootstrap.version||'0.1.0-alpha.3-dev.3';
    renderAccount();renderCategoryNav();renderSidebarAdmin();renderAside();
    $$('[data-nav="messages"]').forEach(el=>el.hidden=!state.user);
    $$('[data-nav="chat"]').forEach(el=>el.hidden=!pluginEnabled('shoutbox'));$$('[data-nav="rankings"]').forEach(el=>el.hidden=!pluginEnabled('rankings'));
    paintIcons();
}
function renderAccount(){const el=$('#account-control');el.innerHTML=state.user?`<button class="user-menu-button" data-action="account" aria-label="${tx('ui.common.account_label',{name:state.user.name})}">${avatar(state.user,'small')}<span>${e(state.user.name)}</span>${icon('chevron-down')}</button>`:`<button class="button button-small button-ghost" data-action="login">${tx('ui.auth.sign_in')}</button>`;}
function renderCategoryNav(){const list=state.bootstrap.categories||[];$('#category-nav').innerHTML=list.length?list.map(c=>`<a class="category-link" data-category-nav="${Number(c.id)}" href="#/category/${Number(c.id)}"><span class="category-dot" style="--tone:${tone(c.color)}"></span><span>${e(c.name)}</span><span class="count">${c.is_private?icon('lock'):compact(c.threads_count)}</span></a>`).join(''):`<span class="muted" style="font-size:11px;padding:10px 13px">${tx('ui.nav.no_categories')}</span>`;}
function renderSidebarAdmin(){$('#sidebar-admin').innerHTML=state.user?.role==='admin'?`<a href="#/admin" class="nav-item" data-nav="admin">${icon('settings')}<span>${tx('ui.nav.admin')}</span></a>`:'';}
function renderAside(){const stats=state.bootstrap.stats||{};$('#right-column').innerHTML=`${pluginEnabled('shoutbox')?shoutPanel():''}${pluginEnabled('rankings')?`<section class="panel"><div class="panel-header"><h2>${icon('trophy')}${tx('ui.aside.helpful')}</h2><span class="minor-label">${tx('ui.aside.ranking')}</span></div><div id="sidebar-rankings" class="ranking-list"><div class="skeleton skeleton-line"></div></div><a href="#/rankings" class="ranking-footer">${tx('ui.aside.full_ranking')}&nbsp; →</a></section>`:''}<section class="panel stats-panel" aria-label="${tx('ui.aside.stats')}"><div class="stats-item"><strong>${compact(stats.users)}</strong><small>${e(noun(stats.users,'people'))}</small></div><div class="stats-item"><strong>${compact(stats.threads)}</strong><small>${e(noun(stats.threads,'topics'))}</small></div><div class="stats-item"><strong>${compact(stats.posts)}</strong><small>${e(noun(stats.posts,'posts'))}</small></div></section><p class="right-note"><strong>${tx('ui.footer.rules')}</strong><br>WojteX Forum by <span class="credit-name">Swir</span> · ${tx('ui.common.development')}</p>`;paintShouts();renderSidebarRankings();}
function shoutPanel(large=false){return `<section class="panel ${large?'shout-panel-full':''}" id="${large?'main-':'side-'}shout-panel"><div class="panel-header"><h2>${icon('chat')}${tx('ui.shout.title')}</h2><span class="minor-label" title="${tx('ui.shout.refresh_title')}"><span class="status-dot"></span>${tx('ui.shout.chat')}</span></div><div class="shout-list" data-shout-list ${large?'style="max-height:570px;min-height:350px"':''} role="log" aria-label="${tx('ui.shout.messages_label')}">${state.shouts.length?'':`<div class="loading-label">${tx('ui.shout.loading')}</div>`}</div>${state.user?`<form class="shout-form" data-form="shout"><div class="shout-input-wrap"><input name="body" placeholder="${tx('ui.shout.placeholder')}" maxlength="1000" required autocomplete="off" aria-label="${tx('ui.shout.message_label')}"><button class="shout-send" type="submit" aria-label="${tx('ui.shout.send')}">${icon('send')}</button></div><div class="shout-hint"><span>${tx('ui.shout.enter')}</span><span>${tx('ui.shout.refresh')}</span></div></form>`:`<div class="shout-login"><p>${tx('ui.shout.join')}</p><button class="button button-small button-secondary" data-action="login">${tx('ui.shout.sign_in')}</button></div>`}</section>`;}
function shoutRow(s){return `<article class="shout-message" data-shout-id="${Number(s.id)}">${avatar(s.author,'small')}<div class="shout-main"><div class="shout-meta"><strong>${e(s.author?.name||tr('ui.user.fallback'))}</strong><time title="${e(dateTitle(s.created_at))}">${e(relative(s.created_at))}</time></div><p>${e(s.body)}</p>${state.user&&(state.user.id===s.author?.id||isMod())?`<button class="shout-delete" data-action="delete-shout" data-id="${Number(s.id)}">${tx('ui.common.delete')}</button>`:''}</div></article>`;}
function paintShouts(){ $$('[data-shout-list]').forEach(list=>{const nearBottom=list.scrollHeight-list.scrollTop-list.clientHeight<70;list.innerHTML=state.shouts.length?state.shouts.map(shoutRow).join(''):'<div class="empty-state compact"><div class="empty-icon">'+icon('chat')+`</div><h3>${tx('ui.shout.start')}</h3><p>${tx('ui.shout.first_message')}</p></div>`;if(nearBottom||!list.dataset.loaded){list.scrollTop=list.scrollHeight;list.dataset.loaded='true';}});}
async function refreshShouts(reset=false){if(!pluginEnabled('shoutbox')||state.shoutsInFlight)return;state.shoutsInFlight=true;try{const r=await request('/api/shouts'+(!reset&&state.lastShoutId?'?after='+state.lastShoutId:''));if(r.enabled===false)return;const incoming=r.data||[];if(reset){state.shouts=incoming;}else{const seen=new Set(state.shouts.map(s=>s.id));state.shouts.push(...incoming.filter(s=>!seen.has(s.id)));}state.shouts=state.shouts.slice(-100);state.lastShoutId=Math.max(0,...state.shouts.map(s=>Number(s.id)));if(reset||incoming.length||!state.shouts.length)paintShouts();}catch(err){if(reset)$$('[data-shout-list]').forEach(el=>el.innerHTML=`<div class="empty-state compact"><p>${e(err.message)}</p><button class="text-button" data-action="refresh-shouts">${tx('ui.common.retry')}</button></div>`);}finally{state.shoutsInFlight=false;}}
async function refreshRankings(){if(!pluginEnabled('rankings'))return;try{const r=await request('/api/rankings');state.rankings=r.data||[];renderSidebarRankings();}catch(_){const el=$('#sidebar-rankings');if(el)el.innerHTML=`<p class="right-note">${tx('ui.rankings.unavailable')}</p>`;}}
function renderSidebarRankings(){const el=$('#sidebar-rankings');if(!el)return;el.innerHTML=state.rankings.length?state.rankings.slice(0,5).map((u,i)=>`<div class="ranking-row"><span class="rank-position ${i===0?'first':''}">${String(i+1).padStart(2,'0')}</span>${avatar(u,'small')}<div class="ranking-info"><strong>${e(u.name)}</strong><small>${e(u.badge||tr('ui.rankings.member'))}</small></div><div class="ranking-score">${count(u.score)}<small>${e(noun(u.score,'points').toUpperCase())}</small></div></div>`).join(''):`<div class="empty-state compact"><p>${tx('ui.rankings.empty_sidebar')}</p></div>`;}

function routeInfo(){const h=location.hash.replace(/^#\/?/,'');const [path,qs]=h.split('?');const parts=(path||'').split('/');return {name:parts[0]||'home',id:Number(parts[1])||null,query:new URLSearchParams(qs||'')};}
function setHeader(title,subtitle,eyebrow=tr('ui.nav.community')){ $('#page-title').innerHTML=title.endsWith('.')?e(title.slice(0,-1))+'<span>.</span>':e(title);$('#page-subtitle').textContent=subtitle;$('#page-eyebrow').textContent=eyebrow;$('#topbar-label').textContent=title; }
function updateNav(route){$$('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===route.name||(route.name==='category'&&el.dataset.nav==='home')));$$('[data-category-nav]').forEach(el=>el.classList.toggle('active',route.name==='category'&&Number(el.dataset.categoryNav)===route.id));closeSidebar();}
async function navigate(){if(!state.bootstrap)return;const token=++state.viewToken;const route=routeInfo();state.route=route;state.thread=null;state.page=Number(route.query.get('page'))||1;state.threadPage=Number(route.query.get('page'))||1;state.sort=route.query.get('sort')||'latest';updateNav(route);$('#main-content').classList.remove('wx-thread-page');const view=$('#view');view.setAttribute('aria-busy','true');view.innerHTML=loading();$('#global-search').value=route.name==='search'?(route.query.get('q')||''):'';$('#workspace-grid').classList.toggle('chat-view',route.name==='chat');try{
    if(['home','latest','category','search','saved'].includes(route.name)){await renderFeed(route,token);}
    else if(route.name==='thread'&&route.id){await renderThread(route.id,token);}
    else if(route.name==='rankings'){await renderRankings(token);}
    else if(route.name==='messages'){await renderPrivateMessages(token);}
    else if(route.name==='chat'){setHeader(tr('ui.shout.header'),tr('ui.shout.subtitle'),tr('ui.shout.eyebrow'));view.innerHTML=pluginEnabled('shoutbox')?`<div class="notice" style="margin-top:0">${tx('ui.shout.notice')}</div>${shoutPanel(true)}`:`<div class="panel">${empty(tr('ui.shout.disabled'),tr('ui.shout.disabled_help'),'chat')}</div>`;paintShouts();await refreshShouts(true);}
    else if(route.name==='login'){setHeader(tr('ui.page.login_title'),tr('ui.page.login_subtitle'));view.innerHTML='<div class="panel">'+empty(tr('ui.page.join'),tr('ui.page.join_help'),'users',`<button class="button button-primary" data-action="login">${tx('ui.auth.sign_in')}</button>`)+'</div>';authModal('login');}
    else if(route.name==='reset-password'){setHeader(tr('ui.auth.reset_title'),tr('ui.auth.reset_subtitle'));view.innerHTML=`<div class="panel">${empty(tr('ui.auth.reset_title'),tr('ui.auth.reset_subtitle'),'lock')}</div>`;resetPasswordModal(route);}
    else if(route.name==='profile'){renderProfile();}
    else if(route.name==='admin'){await renderAdmin(token);}
    else {setHeader(tr('ui.page.not_found_title'),tr('ui.page.not_found_subtitle'));view.innerHTML=`<div class="panel">${empty(tr('ui.page.space_missing'),tr('ui.page.space_missing_help'),'search',`<a class="button button-primary" href="#/">${tx('ui.page.back_to_forum')}</a>`)}</div>`;}
}catch(err){if(token!==state.viewToken)return;view.innerHTML=`<div class="panel">${empty(err.status===404?tr('ui.page.content_missing'):err.status===403?tr('ui.page.private'):tr('ui.page.load_failed'),err.message,err.status===403?'lock':'alert',`<button class="button button-secondary" data-action="retry-view">${tx('ui.common.retry')}</button>`)}</div>`;}finally{if(token===state.viewToken){view.setAttribute('aria-busy','false');paintIcons(view);}}}
function welcomePanel(){if(!pluginEnabled('welcome'))return '';const s=state.bootstrap.settings||{};return `<section class="welcome-panel"><div class="welcome-copy"><div class="welcome-tag">${icon('spark')}${tx('ui.welcome.tag')}</div><h2>${e(s.welcome_title||tr('ui.footer.slogan'))}</h2><p>${e(s.welcome_text||tr('ui.welcome.default_text'))}</p><div class="welcome-actions"><button class="button" data-action="${state.user?'new-topic':'register'}">${e(state.user?tr('ui.welcome.start'):tr('ui.welcome.join'))}${icon('arrow-right')}</button><button class="text-button" data-action="scroll-discussions">${tx('ui.welcome.discover')}${icon('chevron-right')}</button></div></div><div class="welcome-art" aria-hidden="true"><span class="art-bracket">{ }</span><div class="code-card"><div class="code-titlebar"><i></i><i></i><i></i><small>community.ts</small></div><div class="code-body"><span class="code-muted">${tx('ui.welcome.art_comment')}</span><br>community.<b>connect</b>({<br>&nbsp; ideas: <em>'unlimited'</em>,<br>&nbsp; together: <b>true</b><br>});</div></div><div class="art-chip">${icon('check-circle')}${tx('ui.welcome.art_chip')}</div></div></section>`;}
function spaceCards(){const list=(state.bootstrap.categories||[]).filter(c=>!c.parent_id).slice(0,3);return list.length?`<section aria-label="${tx('ui.spaces.label')}"><div class="section-heading"><h2>${tx('ui.spaces.title')}</h2><small>${tx('ui.spaces.available',{count:counted(state.bootstrap.categories.length,'categories')})}</small></div><div class="spaces-grid">${list.map(c=>`<a href="#/category/${Number(c.id)}" class="space-card" style="--tone:${tone(c.color)}"><div class="space-icon">${icon(c.icon||'code')}</div><span class="card-arrow">${icon('arrow-up-right')}</span><h3>${e(c.name)}</h3><p>${e(counted(c.threads_count,'topics'))}${e(c.is_private?tr('ui.common.private_suffix'):'')}</p></a>`).join('')}</div></section>`:'';}
function categoryTag(category){return category?`<a class="tag" href="#/category/${Number(category.id)}" style="--tone:${tone(category.color)}">${e(category.name)}</a>`:'';}
function topicRow(t){return `<article class="topic-row">${avatar(t.author)}<div class="topic-row-content"><div class="topic-tags">${categoryTag(t.category)}${t.is_pinned?`<span class="tag tag-pinned">${icon('pin')}${tx('ui.topic.pinned')}</span>`:''}${t.is_locked?`<span class="tag tag-neutral">${icon('lock')}${tx('ui.topic.closed')}</span>`:''}${t.category?.is_private?`<span class="tag tag-private">${icon('lock')}${tx('ui.topic.private')}</span>`:''}</div><a href="#/thread/${Number(t.id)}" class="topic-title">${e(t.title)}</a>${t.excerpt?`<p class="topic-excerpt">${e(t.excerpt)}</p>`:''}<div class="topic-meta"><span class="author-name">${e(t.author?.name||tr('ui.user.fallback'))}</span><span class="meta-dot">·</span><time title="${e(dateTitle(t.updated_at||t.created_at))}">${e(relative(t.updated_at||t.created_at))}</time>${t.bookmarked?`<span title="${tx('ui.topic.saved_title')}">${icon('bookmark')}</span>`:''}</div></div><a href="#/thread/${Number(t.id)}" class="topic-stats" aria-label="${e(counted(t.replies_count,'replies'))}, ${e(counted(t.views,'views'))}"><span>${icon('message')}${compact(t.replies_count)}</span><span class="stat-views">${icon('eye')}${compact(t.views)}</span></a></article>`;}
async function renderFeed(route,token){const view=$('#view');const category=(state.bootstrap.categories||[]).find(c=>c.id===route.id);let title=tr('ui.feed.home_title');let subtitle=state.bootstrap.settings?.tagline||tr('ui.feed.home_subtitle');if(route.name==='latest'){title=tr('ui.feed.latest_title');subtitle=tr('ui.feed.latest_subtitle');}if(route.name==='category'){title=category?.name||tr('ui.feed.category_title');subtitle=category?.description||tr('ui.feed.category_subtitle');}if(route.name==='search'){title=tr('ui.feed.search_title');subtitle=tr('ui.feed.search_subtitle',{query:route.query.get('q')||''});}if(route.name==='saved'){title=tr('ui.feed.saved_title');subtitle=tr('ui.feed.saved_subtitle');}setHeader(title,subtitle,route.name==='category'?tr('ui.feed.eyebrow_category'):tr('ui.feed.eyebrow'));if(route.name==='saved'&&!state.user){view.innerHTML=`<div class="panel">${empty(tr('ui.feed.saved_empty_title'),tr('ui.feed.saved_login_help'),'bookmark',`<button class="button button-primary" data-action="login">${tx('ui.auth.sign_in')}</button>`)}</div>`;return;}const query=new URLSearchParams({sort:state.sort,page:String(state.page)});if(route.name==='category')query.set('category',String(route.id));if(route.name==='search')query.set('q',route.query.get('q')||'');if(route.name==='saved')query.set('bookmarked','1');const r=await request('/api/threads?'+query);if(token!==state.viewToken)return;view.innerHTML=`${route.name==='home'?welcomePanel()+spaceCards():''}${category?.is_private?`<div class="private-category-banner">${icon('lock')} ${tx('ui.feed.private_notice')}</div>`:''}<section class="panel threads-panel" id="forum-list"><div class="discussion-toolbar"><h2>${e(route.name==='search'?tr('ui.feed.search_results'):route.name==='saved'?tr('ui.feed.saved_discussions'):tr('ui.feed.discussions_title'))}</h2><small>${e(counted(r.total,'topics'))}</small></div><div class="topic-tabs" role="tablist" aria-label="${tx('ui.feed.sort_label')}"><button class="topic-tab ${state.sort==='latest'?'active':''}" role="tab" aria-selected="${state.sort==='latest'}" data-action="sort" data-sort="latest">${icon('clock')}${tx('ui.feed.latest')}</button><button class="topic-tab ${state.sort==='popular'?'active':''}" role="tab" aria-selected="${state.sort==='popular'}" data-action="sort" data-sort="popular">${icon('fire')}${tx('ui.feed.popular')}</button><button class="topic-tab ${state.sort==='unanswered'?'active':''}" role="tab" aria-selected="${state.sort==='unanswered'}" data-action="sort" data-sort="unanswered">${icon('message')}${tx('ui.feed.unanswered')}</button></div><div>${r.data?.length?r.data.map(topicRow).join(''):empty(route.name==='search'?tr('ui.feed.search_empty'):route.name==='saved'?tr('ui.feed.collection_empty'):tr('ui.feed.first_discussion'),route.name==='search'?tr('ui.feed.search_empty_help'):route.name==='saved'?tr('ui.feed.collection_empty_help'):tr('ui.feed.first_help'),'message',route.name==='saved'?'':`<button class="button button-secondary" data-action="new-topic">${icon('plus')}${tx('ui.topic.create')}</button>`)}</div>${pagination(r.current_page||1,r.last_page||1,r.total||0)}</section>`;}
function pagination(current,last,total,label='topics'){if(last<=1)return '';return `<div class="pagination"><span>${tx('ui.pagination.summary',{current:count(current),last:count(last),total:counted(total,label)})}</span><div class="pagination-actions"><button class="button button-ghost" data-action="page" data-page="${current-1}" ${current<=1?'disabled':''} aria-label="${tx('ui.pagination.previous')}">${icon('arrow-left')}</button><button class="button button-ghost" data-action="page" data-page="${current+1}" ${current>=last?'disabled':''} aria-label="${tx('ui.pagination.next')}">${icon('arrow-right')}</button></div></div>`;}
async function renderThread(id,token){
    const r=await request(`/api/threads/${id}?page=${state.threadPage}`);
    if(token!==state.viewToken)return;
    state.thread=r;
    const t=r.thread;
    const canReply=isMod()||(!t.is_locked&&(!state.user||r.can_reply!==false));
    setHeader(t.title,'',t.category?.name||tr('ui.topic.discussion'));
    $('#main-content').classList.add('wx-thread-page');
    $('#view').innerHTML=`
        <nav class="breadcrumb" aria-label="${tx('ui.common.forum')}">
            <a href="#/">${tx('ui.common.forum')}</a>${icon('chevron-right')}
            <a href="#/category/${Number(t.category_id)}">${e(t.category?.name||tr('ui.topic.category'))}</a>${icon('chevron-right')}
            <span aria-current="page">${tx('ui.topic.topic')}</span>
        </nav>
        <section class="panel thread-head" aria-labelledby="thread-title">
            <div class="topic-tags">${categoryTag(t.category)}${t.is_pinned?`<span class="tag tag-pinned">${icon('pin')}${tx('ui.topic.pinned')}</span>`:''}${t.is_locked?`<span class="tag tag-neutral">${icon('lock')}${tx('ui.topic.closed')}</span>`:''}</div>
            <h1 id="thread-title">${e(t.title)}</h1>
            <div class="topic-meta">${avatar(t.author,'small')}<span class="author-name">${e(t.author?.name||tr('ui.user.fallback'))}</span><span class="meta-dot">·</span><time title="${e(dateTitle(t.created_at))}">${e(relative(t.created_at))}</time><span class="meta-dot">·</span><span>${e(counted(t.views,'views'))}</span></div>
            <div class="thread-head-actions">
                ${canReply?`<button class="button button-primary" data-action="focus-reply">${icon('message')}${tx('ui.topic.reply')}</button>`:''}
                <button class="button button-secondary" data-action="bookmark" data-id="${id}" aria-pressed="${!!t.bookmarked}">${icon('bookmark')}${e(t.bookmarked?tr('ui.topic.saved'):tr('ui.topic.save'))}</button>
                <button class="button button-ghost" data-action="copy-thread">${icon('link')}${tx('ui.topic.copy')}</button>
            </div>
            ${isMod()?`<details class="thread-moderation"><summary>${icon('shield')}${tx('ui.topic.moderation')}</summary><div class="thread-head-actions">
                <button class="button button-small button-ghost" data-action="toggle-lock" data-id="${id}">${icon(t.is_locked?'unlock':'lock')}${e(t.is_locked?tr('ui.common.open'):tr('ui.common.close'))}</button>
                <button class="button button-small button-ghost" data-action="toggle-pin" data-id="${id}">${icon('pin')}${e(t.is_pinned?tr('ui.topic.unpin'):tr('ui.topic.pin'))}</button>
                <button class="button button-small button-danger" data-action="delete-thread" data-id="${id}">${icon('trash')}${tx('ui.topic.delete')}</button>
            </div></details>`:''}
        </section>
        <div class="posts-list">${(r.posts||[]).map((p,i)=>postCard(p,(r.page-1)*40+i+1)).join('')}</div>
        ${pagination(r.page||1,r.last_page||1,r.total_posts||r.posts?.length||0,'posts')}${replyForm(t)}`;
}

function postCard(p,number){const canEdit=state.user&&(state.user.id===p.author?.id||isMod())&&(!state.thread?.thread?.is_locked||isMod())&&(state.thread?.can_reply!==false||isMod());return `<article class="panel post-card" id="post-${Number(p.id)}"><div class="post-top">${avatar(p.author)}<div class="post-author"><strong>${e(p.author?.name||tr('ui.user.fallback'))}</strong>${role(p.author)}<small><time title="${e(dateTitle(p.created_at))}">${e(relative(p.created_at))}</time>${e(p.updated_at&&p.updated_at!==p.created_at?tr('ui.common.edited_suffix'):'')}</small></div><span class="post-number">#${number}</span></div><div class="post-body">${p.body_html||e(p.body).replace(/\n/g,'<br>')}</div>${p.attachments?.length?`<div class="attachments">${p.attachments.map(a=>`<a class="attachment" href="/attachments/${Number(a.id)}" target="_blank" rel="noopener noreferrer">${icon('paperclip')}${e(a.name||a.original_name||tr('ui.post.attachment'))}${a.size?`<span class="muted">(${formatBytes(a.size)})</span>`:''}</a>`).join('')}</div>`:''}<div class="post-actions"><div class="post-actions-group"><button class="reaction-button ${p.reacted?'active':''}" data-action="react" data-id="${Number(p.id)}" aria-pressed="${!!p.reacted}" ${state.thread?.can_reply===false?'disabled':state.user?.id===p.author?.id?`disabled title="${tx('ui.post.own_reaction')}"`:''}>${icon('heart')}<span>${count(p.reactions_count)}</span></button>${state.thread?.can_reply===false?'':`<button class="subtle-button" data-action="quote" data-id="${Number(p.id)}">${tx('ui.post.quote')}</button>`}</div>${canEdit?`<div class="post-actions-group"><button class="subtle-button" data-action="edit-post" data-id="${Number(p.id)}">${tx('ui.common.edit')}</button><button class="subtle-button" data-action="attach-post" data-id="${Number(p.id)}">${tx('ui.post.add_file')}</button>${number!==1?`<button class="subtle-button" data-action="delete-post" data-id="${Number(p.id)}">${tx('ui.common.delete')}</button>`:''}</div>`:''}</div></article>`;}
function formatBytes(bytes){const unit=bytes>=1024*1024?'megabyte':'kilobyte';const value=bytes>=1024*1024?bytes/1024/1024:Math.ceil(bytes/1024);return new Intl.NumberFormat(activeLocale(),{style:'unit',unit,unitDisplay:'short',maximumFractionDigits:1}).format(value);}
function editor(name='body',value='',placeholder=tr('ui.editor.placeholder'),syntax='markdown'){return `<div class="editor" data-syntax="${syntax==='bbcode'?'bbcode':'markdown'}"><div class="editor-toolbar"><button type="button" data-action="format" data-format="bold" aria-label="${tx('ui.editor.bold')}"><strong>B</strong></button><button type="button" data-action="format" data-format="italic" aria-label="${tx('ui.editor.italic')}"><em>I</em></button><button type="button" data-action="format" data-format="link" aria-label="${tx('ui.editor.link')}">${icon('link')}</button><button type="button" data-action="format" data-format="code" aria-label="${tx('ui.editor.code')}">${icon('code')}</button><button type="button" data-action="format" data-format="quote" aria-label="${tx('ui.editor.quote')}">${icon('quote')}</button><button type="button" data-action="format" data-format="list" aria-label="${tx('ui.editor.list')}">${icon('list')}</button><small>${syntax==='bbcode'?'BBCODE':'MARKDOWN'}</small></div><textarea name="${e(name)}" placeholder="${e(placeholder)}" required maxlength="50000" aria-label="${tx('ui.editor.body_label')}">${e(value)}</textarea></div>`;}
function replyForm(t){if(state.thread?.can_reply===false&&state.user&&!isMod())return `<section class="panel reply-panel">${empty(tr('ui.groups.read_only'),tr('ui.groups.read_only_help'),'lock')}</section>`;if(t.is_locked&&!isMod())return `<section class="panel reply-panel">${empty(tr('ui.post.closed_title'),tr('ui.post.closed_help'),'lock')}</section>`;if(!state.user)return `<section class="panel reply-panel">${empty(tr('ui.post.perspective_title'),tr('ui.post.sign_in_help'),'message',`<button class="button button-primary" data-action="login">${tx('ui.post.sign_in_reply')}</button>`)}</section>`;return `<section class="panel reply-panel" id="reply-panel"><div class="reply-header">${avatar(state.user)}<div><h3>${tx('ui.post.reply_title')}</h3><small>${tx('ui.post.reply_subtitle')}</small></div></div><form data-form="reply" data-thread="${Number(t.id)}"><div class="form-error" role="alert"></div>${editor()}<div class="reply-bottom"><small>${tx('ui.post.markdown_help')}<br>${tx('ui.post.be_helpful')}</small><button class="button button-primary" type="submit">${tx('ui.post.publish_reply')}${icon('arrow-right')}</button></div></form></section>`;}
async function renderRankings(token){setHeader(tr('ui.rankings.header'),tr('ui.rankings.subtitle'),tr('ui.rankings.eyebrow'));if(!pluginEnabled('rankings')){$('#view').innerHTML=`<div class="panel">${empty(tr('ui.rankings.disabled'),tr('ui.rankings.disabled_help'),'trophy')}</div>`;return;}const r=await request('/api/rankings');if(token!==state.viewToken)return;state.rankings=r.data||[];renderSidebarRankings();$('#view').innerHTML=`<section class="panel ranking-hero"><div class="empty-icon">${icon('trophy')}</div><div><h2>${tx('ui.rankings.hero')}</h2><p>${tx('ui.rankings.explanation')}</p></div></section><section class="panel"><div class="panel-header"><h2>${tx('ui.rankings.overall')}</h2><span class="minor-label">${e(counted(state.rankings.length,'people').toUpperCase())}</span></div>${state.rankings.length?state.rankings.map((u,i)=>`<div class="full-rank-row"><span class="rank-position ${i<3?'first':''}">${String(i+1).padStart(2,'0')}</span>${avatar(u)}<div class="rank-user"><strong>${e(u.name)}${role(u)}</strong><small>${e(u.badge||tr('ui.rankings.member'))}</small></div><div class="rank-metric posts">${count(u.posts_count)}<small>${e(noun(u.posts_count,'posts'))}</small></div><div class="rank-metric score">${count(u.score)}<small>${e(noun(u.score,'points'))}</small></div></div>`).join(''):empty(tr('ui.rankings.first'),tr('ui.rankings.first_help'),'trophy')}</section>`;}
/** Personal inbox: messages stay text, never innerHTML from user content. */
async function renderPrivateMessages(token) {
    const view=$('#view');
    setHeader(tr('ui.messages.title'),tr('ui.messages.subtitle'),tr('ui.messages.eyebrow'));
    if (!state.user) {
        view.innerHTML=`<section class="panel">${empty(tr('ui.messages.login_title'),tr('ui.messages.login_help'),'lock',`<button class="button button-primary" data-action="login">${tx('ui.auth.sign_in')}</button>`)}</section>`;
        return;
    }
    const [result, blockResponse]=await Promise.all([
        request('/api/messages?page='+encodeURIComponent(state.page)),
        request('/api/messages/blocks'),
    ]);
    if(token!==state.viewToken)return;
    const blockedUsers=blockResponse.data||[];
    const blockedIds=new Set(blockedUsers.map(u=>Number(u.id)));
    const entries=(result.data||[]).map(m=>{
        const partner=m.outgoing?m.recipient:m.sender;
        const incoming=!m.outgoing;
        return `<article class="private-message-row ${incoming&&!m.read_at?'unread':''}">
            <div class="private-message-heading">${avatar(partner,'small')}<div><strong>${e(partner?.name||tr('ui.user.fallback'))}</strong><small>${incoming?tx('ui.messages.received'):tx('ui.messages.sent_to')} · ${e(relative(m.created_at))}</small></div></div>
            <p class="private-message-body">${e(m.body)}</p>
            ${incoming&&!m.read_at?`<button type="button" class="button button-small button-secondary" data-action="message-read" data-id="${Number(m.id)}">${icon('check')}${tx('ui.messages.mark_read')}</button>`:''}
            ${incoming?`<button type="button" class="button button-small button-secondary" data-action="message-report" data-id="${Number(m.id)}">${icon('alert')}${tx('ui.reports.report')}</button>`:''}
            <button type="button" class="button button-small button-secondary" data-action="message-hide" data-id="${Number(m.id)}">${icon('trash')}${tx('ui.messages.hide')}</button>
            ${partner&&!blockedIds.has(Number(partner.id))?`<button type="button" class="button button-small button-secondary" data-action="message-block" data-id="${Number(partner.id)}" data-name="${e(partner.name)}">${icon('shield')}${tx('ui.messages.block')}</button>`:''}
        </article>`;
    }).join('');
    const pager=(result.last_page||1)>1?`<nav class="private-message-pager" aria-label="${tx('ui.messages.pages')}">${Array.from({length:Math.min(7,result.last_page)},(_,i)=>i+Math.max(1,Math.min(state.page-3,result.last_page-6))).map(page=>`<a class="button button-small ${page===state.page?'button-primary':'button-secondary'}" href="#/messages?page=${page}">${page}</a>`).join('')}</nav>`:'';
    view.innerHTML=`<section class="panel private-message-compose"><div class="discussion-toolbar"><h2>${tx('ui.messages.compose')}</h2><small>${tx('ui.messages.unread_count',{count:Number(result.unread)||0})}</small></div>
        <form data-form="private-message"><div class="form-error" role="alert"></div>
        <label class="field"><span>${tx('ui.messages.recipient')}</span><input name="recipient_query" minlength="2" maxlength="50" autocomplete="off" placeholder="${tx('ui.messages.recipient_placeholder')}"><small>${tx('ui.messages.recipient_help')}</small></label>
        <button type="button" class="button button-small button-secondary" data-action="message-find">${icon('search')}${tx('ui.messages.recipient_search')}</button>
        <label class="field"><span>${tx('ui.messages.recipient_select')}</span><select name="recipient_id" required><option value="">${tx('ui.messages.recipient_choose')}</option></select></label>
        <p class="form-note" data-recipient-status aria-live="polite"></p>
        <button type="button" class="button button-small button-secondary" data-action="message-block-selected">${icon('shield')}${tx('ui.messages.block_selected')}</button>
        <label class="field"><span>${tx('ui.messages.body')}</span><textarea name="body" minlength="1" maxlength="4000" required placeholder="${tx('ui.messages.body_placeholder')}"></textarea></label>
        <div class="form-footer"><button type="submit" class="button button-primary">${icon('send')}${tx('ui.messages.send')}</button></div></form></section>
        <section class="panel private-message-inbox"><div class="discussion-toolbar"><h2>${tx('ui.messages.mailbox')}</h2></div>
            ${entries||empty(tr('ui.messages.empty'),tr('ui.messages.empty_help'),'message')}${pager}</section>
        <section class="panel private-message-inbox"><div class="discussion-toolbar"><h2>${tx('ui.messages.blocks_title')}</h2></div>
            <p class="form-note">${tx('ui.messages.blocks_help')}</p>
            ${blockedUsers.length?blockedUsers.map(u=>`<article class="private-message-row"><div class="private-message-heading"><strong>${e(u.name)} (#${Number(u.id)})</strong></div><button type="button" class="button button-small button-secondary" data-action="message-unblock" data-id="${Number(u.id)}">${icon('unlock')}${tx('ui.messages.unblock')}</button></article>`).join(''):`<p class="form-note">${tx('ui.messages.blocks_empty')}</p>`}
        </section>`;
}

function renderProfile(){setHeader(tr('ui.profile.title'),tr('ui.profile.subtitle'),tr('ui.profile.eyebrow'));if(!state.user){$('#view').innerHTML=`<div class="panel">${empty(tr('ui.profile.login'),tr('ui.profile.login_help'),'user',`<button class="button button-primary" data-action="login">${tx('ui.auth.sign_in')}</button>`)}</div>`;return;}const u=state.user;$('#view').innerHTML=`<section class="panel profile-card"><div class="profile-overview">${avatar(u,'xl')}<div><h2>${e(u.name)}${role(u)}</h2><p>${e(u.email||'')}</p><p>${parseDate(u.created_at)?tx('ui.profile.member_since',{date:new Intl.DateTimeFormat(activeLocale(),{month:'long',year:'numeric'}).format(parseDate(u.created_at))}):tx('ui.profile.new_member')}</p></div></div><form data-form="profile"><div class="form-error" role="alert"></div><label class="field"><span>${tx('ui.auth.display_name')}</span><input name="name" value="${e(u.name)}" required minlength="2" maxlength="50" autocomplete="nickname"></label><label class="field"><span>${tx('ui.profile.bio')}</span><textarea name="bio" maxlength="500" placeholder="${tx('ui.profile.bio_placeholder')}">${e(u.bio||'')}</textarea><small>${tx('ui.profile.bio_help')}</small></label><label class="checkbox-field"><input type="checkbox" name="allow_private_messages" ${u.allow_private_messages!==false?'checked':''}><span>${tx('ui.profile.allow_private_messages')}</span></label><p class="form-note">${tx('ui.profile.allow_private_messages_help')}</p><div class="form-footer"><button class="button button-primary" type="submit">${icon('check')}${tx('ui.profile.save')}</button></div></form></section><div class="notice">${tx('ui.profile.unavailable')}</div>`;}

async function renderAdmin(token){setHeader(tr('ui.admin.title'),tr('ui.admin.subtitle'),tr('ui.admin.eyebrow'));if(state.user?.role!=='admin'){$('#view').innerHTML=`<div class="panel">${empty(tr('ui.admin.access'),tr('ui.admin.access_help'),'shield',!state.user?`<button class="button button-primary" data-action="login">${tx('ui.auth.sign_in')}</button>`:`<a class="button button-secondary" href="#/">${tx('ui.page.back_to_forum')}</a>`)}</div>`;return;}const data=await request('/api/admin');if(token!==state.viewToken)return;state.admin=data;if(state.adminTab==='languages')await refreshLanguages();if(state.adminTab==='groups')await refreshGroups();if(state.adminTab==='message-reports')await refreshReports();if(token!==state.viewToken)return;renderAdminView();}
function adminTabButton(id,label,ico){return `<button class="admin-tab ${state.adminTab===id?'active':''}" data-action="admin-tab" data-tab="${id}" role="tab" aria-selected="${state.adminTab===id}">${icon(ico)}${e(label)}</button>`;}
function renderAdminView(){if(!state.admin)return;$('#view').innerHTML=`<div class="admin-tabs" role="tablist" aria-label="${tx('ui.nav.admin')}">${adminTabButton('settings',tr('ui.admin.settings'),'settings')}${adminTabButton('categories',tr('ui.admin.categories'),'layers')}${adminTabButton('plugins',tr('ui.admin.plugins'),'puzzle')}${adminTabButton('languages',tr('ui.languages.tab'),'globe')}${adminTabButton('users',tr('ui.admin.users'),'users')}${adminTabButton('groups',tr('ui.groups.tab'),'shield')}${adminTabButton('message-reports',tr('ui.reports.tab'),'alert')}${adminTabButton('import',tr('ui.admin.import'),'database')}</div><section class="panel admin-panel">${state.adminTab==='settings'?adminSettings():state.adminTab==='categories'?adminCategories():state.adminTab==='plugins'?adminPlugins():state.adminTab==='users'?adminUsers():state.adminTab==='languages'?adminLanguages():state.adminTab==='groups'?adminGroups():state.adminTab==='message-reports'?adminReports():adminImport()}</section>`;if(state.adminTab==='import'&&state.importReport)renderImportReport();}
function adminSettings(){const s=state.admin.settings||state.bootstrap.settings;const stats=state.admin.stats||state.bootstrap.stats;return `<div class="admin-intro"><h2>${tx('ui.admin.settings_title')}</h2><p>${tx('ui.admin.settings_subtitle')}</p></div><div class="admin-metrics"><div class="admin-metric"><strong>${count(stats.users)}</strong><span>${e(noun(stats.users,'people'))}</span></div><div class="admin-metric"><strong>${count(stats.threads)}</strong><span>${e(noun(stats.threads,'topics'))}</span></div><div class="admin-metric"><strong>${count(stats.posts)}</strong><span>${e(noun(stats.posts,'posts'))}</span></div></div><form data-form="settings"><div class="form-error" role="alert"></div><label class="field"><span>${tx('ui.admin.site_name')}</span><input name="site_name" value="${e(s.site_name)}" required minlength="2" maxlength="80"></label><label class="field"><span>${tx('ui.admin.tagline')}</span><input name="tagline" value="${e(s.tagline)}" required maxlength="160"></label><label class="field"><span>${tx('ui.admin.welcome_title')}</span><input name="welcome_title" value="${e(s.welcome_title)}" required maxlength="180"></label><label class="field"><span>${tx('ui.admin.welcome_text')}</span><textarea name="welcome_text" required maxlength="500" style="min-height:90px">${e(s.welcome_text)}</textarea></label><div class="form-row"><label class="field"><span>${tx('ui.admin.theme')}</span><select name="theme">${['dark','midnight','light','system'].map(mode=>`<option value="${mode}" ${s.theme===mode?'selected':''}>${tx('ui.appearance.'+mode)}</option>`).join('')}</select></label><label class="field"><span>${tx('ui.admin.accent')}</span><select name="accent">${['blue','violet','cyan','green','amber','rose'].map(accent=>`<option value="${accent}" ${s.accent===accent?'selected':''}>${tx('ui.appearance.'+accent)}</option>`).join('')}</select></label></div><label class="checkbox-field"><input type="checkbox" name="registration_open" ${s.registration_open?'checked':''}><span>${tx('ui.admin.registration')}</span></label><div class="form-footer"><button class="button button-primary" type="submit">${icon('check')}${tx('ui.admin.save_settings')}</button></div></form>${state.admin.recent_actions?.length?`<h3 class="admin-section-heading">${tx('ui.admin.recent_actions')}</h3>${state.admin.recent_actions.slice(0,8).map(a=>`<div class="audit-row">${tx('ui.audit.'+a.action,{},a.action)}<time>${e(dateTitle(a.created_at))}</time></div>`).join('')}`:''}`;}
function adminCategories(){const categories=state.admin.categories||state.bootstrap.categories||[];return `<div class="admin-intro"><h2>${tx('ui.admin.categories_title')}</h2><p>${tx('ui.admin.categories_subtitle')}</p></div><button class="button button-secondary button-small" data-action="new-category">${icon('plus')}${tx('ui.category.create')}</button>${categories.length?categories.map(c=>`<div class="plugin-card"><span class="plugin-icon" style="color:${tone(c.color)};background:color-mix(in srgb,${tone(c.color)} 12%,transparent)">${icon(c.icon)}</span><div class="plugin-copy"><h3>${e(c.name)}${c.is_private?` <span class="tag tag-private">${tx('ui.topic.private')}</span>`:''}</h3><p>${e(c.description||tr('ui.common.no_description'))}</p><small>${e(counted(c.threads_count,'topics'))}</small></div><button class="icon-button" data-action="edit-category" data-id="${Number(c.id)}" aria-label="${tx('ui.admin.edit_category',{name:c.name})}">${icon('edit')}</button><button class="switch" role="switch" aria-label="${tx('ui.admin.public_access',{name:c.name})}" aria-checked="${!c.is_private}" data-action="category-visibility" data-id="${Number(c.id)}" title="${e(c.is_private?tr('ui.admin.make_public'):tr('ui.admin.make_private'))}"></button></div>`).join(''):empty(tr('ui.admin.first_category'),tr('ui.admin.first_category_help'),'layers')}<div class="notice warning"><strong>${tx('ui.admin.import_private')}</strong><p>${tx('ui.admin.import_private_help')}</p></div>`;}
function adminPlugins(){return `<div class="admin-intro"><h2>${tx('ui.admin.plugins_title')}</h2><p>${tx('ui.admin.plugins_subtitle')}</p></div>${(state.admin.plugins||[]).map(p=>{const id=p.id||p.key;return `<div class="plugin-card"><span class="plugin-icon">${icon(id==='shoutbox'?'chat':id==='rankings'?'trophy':id==='welcome'?'spark':'puzzle')}</span><div class="plugin-copy"><h3>${e(p.name)}</h3><p>${e(p.description)}</p><small>${e(p.version||'0.1.0')}${p.author?' · '+e(p.author):''}</small></div><button class="switch" role="switch" aria-checked="${!!p.enabled}" aria-label="${tx('ui.admin.module_label',{name:p.name})}" data-action="toggle-plugin" data-id="${e(id)}" data-enabled="${p.enabled?'1':'0'}"></button></div>`;}).join('')}<div class="notice"><strong>${tx('ui.admin.extensions_title')}</strong><p>${tx('ui.admin.extensions_help')}</p></div>`;}
function adminUsers(){const users=state.adminUserMatches===null?(state.admin.users||[]):state.adminUserMatches;return `<div class="admin-intro"><h2>${tx('ui.admin.users_title')}</h2><p>${tx('ui.admin.users_subtitle')}</p></div>
<form data-form="admin-user-search" class="form-row"><div class="form-error" role="alert"></div><label class="field"><span>${tx('ui.admin.search_users_label')}</span><input name="q" value="${e(state.adminUserTerm)}" minlength="2" maxlength="80" required placeholder="${tx('ui.admin.search_users_hint')}"></label><div class="field"><span>&nbsp;</span><button class="button button-secondary" type="submit">${icon('search')}${tx('ui.admin.search_users_button')}</button>${state.adminUserMatches!==null?`<button type="button" class="button button-small button-secondary" data-action="admin-users-reset">${tx('ui.admin.search_users_reset')}</button>`:''}</div></form>
<p class="form-note">${state.adminUserMatches===null?tx('ui.admin.search_users_help'):state.adminUserMatches.length?tx('ui.admin.search_users_count',{count:count(state.adminUserMatches.length)}):tx('ui.admin.search_users_none')}</p>${users.map(u=>`<div class="admin-user">${avatar(u)}<div class="admin-user-info"><strong>${e(u.name)} <small>(#${Number(u.id)})</small>${role(u)}${u.is_banned?` <span class="tag tag-private">${tx('ui.admin.blocked')}</span>`:''}</strong><small>${e(u.email||tr('ui.admin.joined',{date:relative(u.created_at)}))}</small></div>${u.role!=='admin'&&u.id!==state.user?.id?`<button class="button button-small ${u.is_banned?'button-secondary':'button-danger'}" data-action="ban-user" data-id="${Number(u.id)}" data-banned="${u.is_banned?'1':'0'}">${e(u.is_banned?tr('ui.common.unblock'):tr('ui.common.block'))}</button>`:''}</div>`).join('')}${!users.length?empty(tr('ui.admin.no_users'),tr('ui.admin.no_users_help'),'users'):''}`;}
function adminGroups(){
    const groups=state.groupData?.groups||[];
    const users=state.admin?.users||[];
    const selectedUsers=state.groupUserMatches===null?users:state.groupUserMatches;
    const categories=(state.admin?.categories||[]).filter(c=>c.is_private);
    return `<div class="admin-intro"><h2>${tx('ui.groups.title')}</h2><p>${tx('ui.groups.subtitle')}</p></div>
    <div class="notice warning">${tx('ui.groups.scope')}</div>
    <form data-form="group-create" class="language-default-form"><div class="form-error" role="alert"></div><label class="field"><span>${tx('ui.groups.name')}</span><input name="name" minlength="2" maxlength="80" required placeholder="${tx('ui.groups.name_hint')}"></label><div class="form-footer"><button class="button button-primary" type="submit">${icon('plus')}${tx('ui.groups.create')}</button></div></form>
    <form data-form="group-user-search" class="form-row" style="margin-top:18px"><div class="form-error" role="alert"></div><label class="field"><span>${tx('ui.groups.search_label')}</span><input name="q" value="${e(state.groupUserTerm||'')}" minlength="2" maxlength="80" required placeholder="${tx('ui.groups.search_hint')}"></label><div class="field"><span>&nbsp;</span><button class="button button-secondary" type="submit">${icon('search')}${tx('ui.groups.search_button')}</button>${state.groupUserMatches!==null?`<button class="button button-small button-secondary" type="button" data-action="group-clear-search">${tx('ui.groups.clear_search')}</button>`:''}</div></form>
    <p class="form-note">${state.groupUserMatches===null?tx('ui.groups.search_help'):state.groupUserMatches.length?tx('ui.groups.search_results',{count:count(state.groupUserMatches.length)}):tx('ui.groups.search_empty')}</p>
    ${groups.length?groups.map(group=>{
       const members=users.filter(u=>group.member_ids?.includes(u.id));
       return `<article class="panel" style="padding:18px;margin-top:18px;background:var(--surface,#151827)">
         <div class="plugin-card"><span class="plugin-icon">${icon('users')}</span><div class="plugin-copy"><h3>${e(group.name)}</h3><small>${tx('ui.groups.members',{count:count(group.member_count??members.length)})}</small></div><button class="button button-small button-danger" type="button" data-action="group-delete" data-id="${Number(group.id)}">${tx('ui.common.delete')}</button></div>
         <form data-form="group-rename" data-id="${Number(group.id)}" class="form-row"><div class="form-error" role="alert"></div><label class="field"><span>${tx('ui.groups.rename')}</span><input name="name" value="${e(group.name)}" minlength="2" maxlength="80" required></label><div class="field"><span>&nbsp;</span><button type="submit" class="button button-small button-secondary">${tx('ui.common.save_changes')}</button></div></form>
         <h3 class="admin-section-heading">${tx('ui.groups.members_label')}</h3><p class="form-note">${members.length?members.map(u=>e(u.name)).join(' · '):tx('ui.groups.no_members')}</p>
         <form data-form="group-member" data-id="${Number(group.id)}"><div class="form-error" role="alert"></div><div class="form-row"><label class="field"><span>${tx('ui.groups.user')}</span><select name="user_id" required>${selectedUsers.length?selectedUsers.map(u=>`<option value="${Number(u.id)}">${e(u.name)} (#${Number(u.id)})${state.groupUserMatches!==null&&u.group_ids?.includes(group.id)?` · ${tx('ui.groups.already_member')}`:''}${u.is_banned?` · ${tx('ui.admin.blocked')}`:''}</option>`).join(''):`<option value="">${tx('ui.groups.search_empty')}</option>`}</select></label><label class="field"><span>${tx('ui.groups.action')}</span><select name="enabled"><option value="1">${tx('ui.groups.add')}</option><option value="0">${tx('ui.groups.remove')}</option></select></label></div><div class="form-footer"><button type="submit" class="button button-small button-primary" ${selectedUsers.length?'':'disabled'}>${tx('ui.groups.save_member')}</button></div></form>
         <h3 class="admin-section-heading">${tx('ui.groups.private_rooms')}</h3>
         ${categories.length?categories.map(category=>{const access=group.permissions?.find(p=>p.category_id===category.id)||{};return `<form data-form="group-permission" data-id="${Number(group.id)}" data-category="${Number(category.id)}" style="margin:12px 0;padding:12px;border:1px solid var(--border,#39394a);border-radius:12px"><div class="form-error" role="alert"></div><strong>${e(category.name)}</strong><div class="form-row"><label class="checkbox-field"><input type="checkbox" name="view" ${access.view?'checked':''}><span>${tx('ui.groups.view')}</span></label><label class="checkbox-field"><input type="checkbox" name="create" ${access.create?'checked':''}><span>${tx('ui.groups.create_topics')}</span></label><label class="checkbox-field"><input type="checkbox" name="reply" ${access.reply?'checked':''}><span>${tx('ui.groups.reply')}</span></label></div><button class="button button-small button-secondary" type="submit">${tx('ui.groups.save_rights')}</button></form>`;}).join(''):`<p class="form-note">${tx('ui.groups.no_private')}</p>`}
         </article>`;
    }).join(''):`<p class="form-note">${tx('ui.groups.no_groups')}</p>`}`;
}
function adminLanguages(){
    const languages=state.languageData?.languages||i18n.languages||[];
    const defaultLocale=state.languageData?.default_locale||state.admin.settings?.default_locale||state.bootstrap.settings?.default_locale||i18n.locale;
    const options=languages.map(language=>`<option value="${e(language.code)}" ${language.code===defaultLocale?'selected':''}>${e(language.native_name||language.name)} (${e(language.code)})</option>`).join('');
    return `<div class="admin-intro"><h2>${tx('ui.languages.title')}</h2><p>${tx('ui.languages.subtitle')}</p></div>
        <form data-form="language-default" class="language-default-form"><div class="form-error" role="alert"></div><label class="field"><span>${tx('ui.languages.default')}</span><select name="default_locale" required>${options}</select><small>${tx('ui.languages.default_help')}</small></label><div class="form-footer"><button class="button button-primary" type="submit">${icon('check')}${tx('ui.languages.save_default')}</button></div></form>
        <h3 class="admin-section-heading">${tx('ui.languages.catalog')}</h3><div class="language-catalog">${languages.map(language=>{const coverage=Math.max(0,Math.min(100,Number(language.coverage)||0));return `<article class="language-card"><div class="language-card-heading"><span class="plugin-icon">${icon('globe')}</span><div><h4>${e(language.native_name||language.name)} <span class="language-code">${e(language.code)}</span></h4><p>${e(language.name)} · ${tx('ui.languages.version',{version:language.version})}</p></div><span class="tag ${language.builtin?'tag-neutral':''}">${tx(language.builtin?'ui.languages.builtin':'ui.languages.custom')}</span></div><div class="language-progress-label"><span>${tx('ui.languages.coverage',{percent:count(coverage)})}</span><span>${tx(Number(language.missing_count)>0?'ui.languages.missing':'ui.languages.complete',{count:count(language.missing_count)})}</span></div><div class="language-progress" role="progressbar" aria-label="${e(language.native_name||language.name)}" aria-valuenow="${coverage}" aria-valuemin="0" aria-valuemax="100"><span style="width:${coverage}%"></span></div></article>`;}).join('')}</div>
        <h3 class="admin-section-heading">${tx('ui.languages.install_title')}</h3><p class="form-note">${tx('ui.languages.install_help')}</p><div class="language-templates"><a class="button button-secondary button-small" href="/api/admin/languages/template?locale=en" download>${icon('download')}${tx('ui.languages.template_en')}</a><a class="button button-secondary button-small" href="/api/admin/languages/template?locale=pl" download>${icon('download')}${tx('ui.languages.template_pl')}</a></div>
        <form data-form="language-upload"><div class="form-error" role="alert"></div><label class="field"><span>${tx('ui.languages.file')}</span><input type="file" name="file" accept="application/json,.json" required><small>${tx('ui.languages.file_help')}</small></label><label class="checkbox-field"><input type="checkbox" name="replace"><span>${tx('ui.languages.replace')}</span></label><p class="form-note">${tx('ui.languages.replace_help')}</p><div class="form-footer"><button class="button button-primary" type="submit">${icon('plus')}${tx('ui.languages.install')}</button></div></form>`;
}
