function closeSidebar(){$('#sidebar').classList.remove('open');$('#sidebar-backdrop').classList.remove('visible');}
function updateRouteQuery(values){const route=routeInfo();Object.entries(values).forEach(([k,v])=>v===null?route.query.delete(k):route.query.set(k,String(v)));const base=route.name==='home'?'':route.name+(route.id?'/'+route.id:'');location.hash='/'+base+(route.query.size?'?'+route.query.toString():'');}
function reportReasonLabel(reason){
    const labels={spam:tx('ui.reports.reason_spam'),harassment:tx('ui.reports.reason_harassment'),
        threat:tx('ui.reports.reason_threat'),other:tx('ui.reports.reason_other')};
    return labels[reason]||labels.other;
}
function adminReports(){
    const page=state.reportData||{data:[],current_page:1,last_page:1};
    const filters=['open','resolved','dismissed'].map(status=>`<button type="button" class="button button-small ${state.reportStatus===status?'button-primary':'button-secondary'}" data-action="reports-filter" data-status="${status}">${tx('ui.reports.'+status)}</button>`).join(' ');
    const rows=(page.data||[]).map(r=>`<article class="private-message-row">
        <div class="private-message-heading"><strong>${tx('ui.reports.item',{id:Number(r.id)})}</strong><small>${e(relative(r.created_at))}</small></div>
        <p class="form-note">${tx('ui.reports.who',{sender:r.sender_name,recipient:r.recipient_name,reporter:r.reporter_name})}</p>
        <p class="form-note">${tx('ui.reports.reason_label')}: ${reportReasonLabel(r.reason)}</p>
        ${r.details?`<p class="private-message-body">${e(r.details)}</p>`:''}
        <p class="private-message-body">${e(r.body)}</p>
        <div class="form-footer">
            ${r.status!=='resolved'?`<button class="button button-small button-secondary" type="button" data-action="reports-review" data-id="${Number(r.id)}" data-status="resolved">${tx('ui.reports.resolve')}</button>`:''}
            ${r.status!=='dismissed'?`<button class="button button-small button-secondary" type="button" data-action="reports-review" data-id="${Number(r.id)}" data-status="dismissed">${tx('ui.reports.dismiss')}</button>`:''}
            ${r.status!=='open'?`<button class="button button-small button-secondary" type="button" data-action="reports-review" data-id="${Number(r.id)}" data-status="open">${tx('ui.reports.reopen')}</button>`:''}
        </div></article>`).join('');
    const pages=`<div class="form-footer"><button type="button" class="button button-small button-secondary" data-action="reports-page" data-page="${Math.max(1,page.current_page-1)}" ${page.current_page<=1?'disabled':''}>${tx('ui.reports.previous')}</button><small>${page.current_page} / ${page.last_page}</small><button type="button" class="button button-small button-secondary" data-action="reports-page" data-page="${page.current_page+1}" ${page.current_page>=page.last_page?'disabled':''}>${tx('ui.reports.next')}</button></div>`;
    return `<div class="admin-intro"><h2>${tx('ui.reports.title')}</h2><p>${tx('ui.reports.scope')}</p></div>
        <div class="form-footer">${filters}</div>${rows||`<p class="form-note">${tx('ui.reports.empty')}</p>`}${pages}`;
}
async function refreshReports(){
    state.reportData=await request('/api/admin/message-reports?status='+encodeURIComponent(state.reportStatus)+'&page='+encodeURIComponent(state.reportPage));
}
